INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cj-c-tenari-a-knihy_0','Co je hlavní myšlenka textu?',ARRAY['jméno autora','nejdůležitější sdělení','nejdelší věta','poslední slovo']::TEXT[],1,'Hlavní myšlenka shrnuje, co chce text říct.',1,ARRAY[]::TEXT[],NULL,0,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_cj-c-tenari-a-knihy_1','Kdo text napsal?',ARRAY['autor','postava','ilustrátor vždy','čtenář']::TEXT[],0,'Autor je člověk, který text vytvořil.',1,ARRAY[]::TEXT[],NULL,1,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_cj-c-tenari-a-knihy_2','Co je odstavec?',ARRAY['znaménko','jedno písmeno','část textu s jedním tematickým celkem','název knihy']::TEXT[],2,'Odstavec sdružuje věty k jednomu tématu.',2,ARRAY[]::TEXT[],NULL,2,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_cj-c-tenari-a-knihy_3','Co znamená vyhledat informaci v textu?',ARRAY['vymyslet si odpověď','spočítat písmena','přepsat nadpis','najít odpověď přímo v textu']::TEXT[],3,'Informaci ověřujeme v přečteném textu.',3,ARRAY[]::TEXT[],NULL,3,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_cj-c-tenari-a-knihy_4','Co je přímá řeč?',ARRAY['doslovná slova postavy','popis počasí','shrnutí knihy','název kapitoly']::TEXT[],0,'Přímá řeč zachycuje přesné vyjádření mluvčího.',4,ARRAY[]::TEXT[],NULL,4,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_cj-c-tenari-a-knihy_5','Které tvrzení správně rozlišuje autora a vypravěče?',ARRAY['Autor knihu píše; vypravěč je hlas, který v příběhu vypráví.','Vypravěč je vždy hlavní hrdina.','Vypravěč knihu vydává a autor ji čte.','Autor a vypravěč jsou vždy tatáž postava.']::TEXT[],0,'Vypravěč je součást způsobu vyprávění, zatímco autor je skutečný tvůrce.',5,ARRAY[]::TEXT[],NULL,5,'c_cj-c-tenari-a-knihy',NULL,NOW()),
('q_lit-basne-a-rymy_0','Jak se nazývá jeden řádek básně?',ARRAY['verš','odstavec','děj','kapitola']::TEXT[],0,'Verš je jeden řádek básně.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-basne-a-rymy',NULL,NOW()),
('q_lit-basne-a-rymy_1','Co je sloka?',ARRAY['název autora','knižní obálka','jedno písmeno','skupina veršů']::TEXT[],3,'Sloka je část básně složená z veršů.',1,ARRAY[]::TEXT[],NULL,1,'c_lit-basne-a-rymy',NULL,NOW()),
('q_lit-basne-a-rymy_2','Co je rým?',ARRAY['název básně','zvuková shoda na konci veršů','hlavní postava','druh prózy']::TEXT[],1,'Rým spojuje verše podobným zakončením.',2,ARRAY[]::TEXT[],NULL,2,'c_lit-basne-a-rymy',NULL,NOW()),
('q_lit-basne-a-rymy_3','Jaký rým má schéma ABAB?',ARRAY['sdružený','střídavý','bez rýmu','obkročný']::TEXT[],1,'U střídavého rýmu se střídají první a třetí verš s druhým a čtvrtým.',3,ARRAY[]::TEXT[],NULL,3,'c_lit-basne-a-rymy',NULL,NOW()),
('q_lit-basne-a-rymy_4','Co v básni vyjadřuje náladu?',ARRAY['obrazy a jazyk básně','číslo stránky','jméno nakladatele','cena knihy']::TEXT[],0,'Náladu vytvářejí volená slova, obrazy a rytmus.',4,ARRAY[]::TEXT[],NULL,4,'c_lit-basne-a-rymy',NULL,NOW()),
('q_lit-basne-a-rymy_5','Které schéma veršů označuje střídavý rým?',ARRAY['ABBA','ABAB','AAAA','AABB']::TEXT[],1,'Ve střídavém rýmu se rýmují první a třetí, druhý a čtvrtý verš.',5,ARRAY[]::TEXT[],NULL,5,'c_lit-basne-a-rymy',NULL,NOW()),
('q_nj-kazdodenni-komunikace_0','Co znamená Guten Morgen?',ARRAY['Dobrou noc','Na shledanou','Dobré ráno','Děkuji']::TEXT[],2,'Guten Morgen používáme ráno.',1,ARRAY[]::TEXT[],NULL,0,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_1','Jak se německy řekne děkuji?',ARRAY['Danke','Hallo','Bitte','Tschüss']::TEXT[],0,'Danke znamená děkuji.',1,ARRAY[]::TEXT[],NULL,1,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_2','Ich bin zwölf Jahre alt. Který tvar slovesa je správně?',ARRAY['bist','ist','bin','sind']::TEXT[],2,'Se zájmenem ich používáme bin.',2,ARRAY[]::TEXT[],NULL,2,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_3','Co znamená Wie viel kostet das?',ARRAY['Jak se jmenuješ?','Kolik to stojí?','Kde bydlíš?','Kolik je hodin?']::TEXT[],1,'Tato věta se ptá na cenu.',2,ARRAY[]::TEXT[],NULL,3,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_4','Jaký člen má slovo Haus?',ARRAY['die','der','den','das']::TEXT[],3,'Říkáme das Haus.',3,ARRAY[]::TEXT[],NULL,4,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_5','Jak německy zdvořile požádáš o účet v restauraci?',ARRAY['Die Rechnung, bitte.','Ich heiße Rechnung.','Der Bahnhof, bitte.','Wie alt sind Sie?']::TEXT[],0,'Die Rechnung znamená účet; bitte je prosím.',4,ARRAY[]::TEXT[],NULL,5,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_nj-kazdodenni-komunikace_6','Doplň: Können Sie mir bitte sagen, wo der Bahnhof …?',ARRAY['sein','sind','bist','ist']::TEXT[],3,'V nepřímé otázce stojí časované sloveso na konci vedlejší věty: wo der Bahnhof ist.',5,ARRAY[]::TEXT[],NULL,6,'c_nj-kazdodenni-komunikace',NULL,NOW()),
('q_rj-cestovani_0','Co znamená ruské слово город?',ARRAY['letiště','škola','město','vesnice']::TEXT[],2,'Город znamená město.',1,ARRAY[]::TEXT[],NULL,0,'c_rj-cestovani',NULL,NOW()),
('q_rj-cestovani_1','Jak se rusky řekne vlak?',ARRAY['самолёт','поезд','автобус','корабль']::TEXT[],1,'Поезд znamená vlak.',1,ARRAY[]::TEXT[],NULL,1,'c_rj-cestovani',NULL,NOW()),
('q_rj-cestovani_2','Co znamená Где находится вокзал?',ARRAY['Kde je hotel?','Kdy jede vlak?','Kolik stojí lístek?','Kde je nádraží?']::TEXT[],3,'Вокзал je nádraží.',2,ARRAY[]::TEXT[],NULL,2,'c_rj-cestovani',NULL,NOW()),
('q_rj-cestovani_3','Jak se rusky řekne jízdenka?',ARRAY['карта','паспорт','сумка','билет']::TEXT[],3,'Билет znamená jízdenka nebo lístek.',3,ARRAY[]::TEXT[],NULL,3,'c_rj-cestovani',NULL,NOW()),
('q_rj-cestovani_4','Co znamená направо?',ARRAY['doleva','rovně','zpět','doprava']::TEXT[],3,'Направо znamená doprava.',4,ARRAY[]::TEXT[],NULL,4,'c_rj-cestovani',NULL,NOW()),
('q_rj-cestovani_5','Jak rusky požádáš o jízdenku do Moskvy?',ARRAY['Билет к Москве есть.','Билет до Москвы, пожалуйста.','Москва билет, спасибо.','Билет из Москва, пожалуйста.']::TEXT[],1,'Po до je druhý pád: до Москвы.',5,ARRAY[]::TEXT[],NULL,5,'c_rj-cestovani',NULL,NOW()),
('q_mat-procenta-v-praxi_0','Kolik je 10 % ze 100?',ARRAY['10','1','50','100']::TEXT[],0,'Deset procent ze sta je deset.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_1','Kolik je 50 % z 80?',ARRAY['40','30','20','60']::TEXT[],0,'Polovina z 80 je 40.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_2','Kolik korun je sleva 20 % z 500 Kč?',ARRAY['80 Kč','400 Kč','100 Kč','20 Kč']::TEXT[],2,'500 · 0,20 = 100 Kč.',2,ARRAY[]::TEXT[],NULL,2,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_3','Kolik stojí věc za 500 Kč po slevě 20 %?',ARRAY['300 Kč','400 Kč','600 Kč','480 Kč']::TEXT[],1,'Po slevě zůstává 80 % ceny: 500 · 0,8 = 400.',3,ARRAY[]::TEXT[],NULL,3,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_4','Kolik je 25 % jako desetinné číslo?',ARRAY['0,25','0,025','2,5','25']::TEXT[],0,'Procenta dělíme stem: 25 % = 0,25.',4,ARRAY[]::TEXT[],NULL,4,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_5','Cena 800 Kč se nejprve zvýší o 25 % a potom sníží o 20 %. Kolik činí výsledná cena?',ARRAY['840 Kč','960 Kč','760 Kč','800 Kč']::TEXT[],3,'800 × 1,25 × 0,8 = 800; dvě procentní změny se navzájem vyruší.',5,ARRAY[]::TEXT[],NULL,5,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_6','Kolik je 5 % z 200 Kč?',ARRAY['210 Kč','10 Kč','195 Kč','5 Kč']::TEXT[],1,'5 % z 200 Kč je 200 · 5/100 = 10 Kč.',1,ARRAY[]::TEXT[],NULL,6,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_7','Kolik je 10 % z 350 Kč?',ARRAY['35 Kč','10 Kč','385 Kč','340 Kč']::TEXT[],0,'10 % z 350 Kč je 350 · 10/100 = 35 Kč.',1,ARRAY[]::TEXT[],NULL,7,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_8','Kolik je 25 % z 640 Kč?',ARRAY['160 Kč','800 Kč','615 Kč','25 Kč']::TEXT[],0,'25 % z 640 Kč je 640 · 25/100 = 160 Kč.',1,ARRAY[]::TEXT[],NULL,8,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_9','Kolik je 40 % z 900 Kč?',ARRAY['40 Kč','360 Kč','860 Kč','1260 Kč']::TEXT[],1,'40 % z 900 Kč je 900 · 40/100 = 360 Kč.',1,ARRAY[]::TEXT[],NULL,9,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_10','Jaká je sleva 25 % z ceny 240 Kč?',ARRAY['60 Kč','300 Kč','25 Kč','240 Kč']::TEXT[],0,'Sleva je 240 · 25/100 = 60 Kč.',2,ARRAY[]::TEXT[],NULL,10,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_11','Jaká je sleva 20 % z ceny 750 Kč?',ARRAY['20 Kč','750 Kč','150 Kč','900 Kč']::TEXT[],2,'Sleva je 750 · 20/100 = 150 Kč.',2,ARRAY[]::TEXT[],NULL,11,'c_mat-procenta-v-praxi',NULL,NOW()),
('q_mat-procenta-v-praxi_12','Jaká je sleva 15 % z ceny 1200 Kč?',ARRAY['15 Kč','1380 Kč','1200 Kč','180 Kč']::TEXT[],3,'Sleva je 1200 · 15/100 = 180 Kč.',2,ARRAY[]::TEXT[],NULL,12,'c_mat-procenta-v-praxi',NULL,NOW()),
